  'vmovexa_dooh_engine': 'VMOVEXA DOOH इंजन',
  'advertiser_faq1_a': 'अभियान पर जाएं और "अभियान बनाएं" पर टैप करें। बुनियादी जानकारी दर्ज करने, अपनी 16:9 क्रिएटिव सामग्री अपलोड करने, लक्षित बेड़े का चयन करने, शेड्यूल व बजट कॉन्फ़िगर करने और सत्यापन के लिए सबमिट करने हेतु चरणबद्ध सेटअप का पालन करें।',
  'advertiser_faq1_q': 'ट्रांजिट विज्ञापन अभियान कैसे बनाएं और लॉन्च करें?',
  'advertiser_faq2_a': 'हम MP4 (H.264), JPG, PNG और HTML5 ज़िप पैकेज का समर्थन करते हैं। मानक रिज़ॉल्यूशन 1920×1080 (16:9 पहलू अनुपात) है, वीडियो विज्ञापनों के लिए अधिकतम अवधि 30 सेकंड है, और फ़ाइल का आकार 50 MB से कम होना चाहिए।',
  'advertiser_faq2_q': 'अनुशंसित क्रिएटिव विनिर्देश क्या हैं?',
  'advertiser_faq3_a': 'प्रत्येक अभियान एक ट्रैक करने योग्य QR पहचान उत्पन्न करता है। जब यात्री स्क्रीन पर प्रदर्शित QR कोड को स्कैन करते हैं, तो सिस्टम समय, स्थान, वाहन आईडी रिकॉर्ड करता है और उन्हें आपके लैंडिंग पृष्ठ पर पुनर्निर्देशित करता है।',
  'advertiser_faq3_q': 'स्मार्ट QR कोड लीड एट्रिब्यूशन कैसे काम करता है?',
  'advertiser_faq4_a': 'अभियानों पर दैनिक या कुल बजट मॉडल पर शुल्क लिया जाता है। विज्ञापन खर्च पर GST (18%) की गणना की जाती है। सत्यापन अनुमोदन पर कर क्रेडिट वाले चालान स्वचालित रूप से उत्पन्न होते हैं।',
